text:
{
  "title_novice": "Почему СП «проседает» против коллектора",
  "summary": [
    {"text": "На диаграмме СП пласт-коллектор при пресном глинистом растворе даёт пониженные значения относительно линии глин.", "claims": ["c3", "c4", "c7"]},
    {"text": "Величина этой аномалии растёт вместе с контрастом вод и глинистости: чем больше различие, тем больше аномалия.", "claims": ["c5", "c6"]},
    {"text": "Поэтому отрицательная аномалия давно служит признаком коллектора в терригенном разрезе.", "claims": ["c1", "c2"]}
  ],
  "claims": [
    {"key": "c1", "text": "Методы глинистости — СП и гамма-метод — широко применяют для выделения коллекторов в терригенном разрезе.", "kind": "observation", "unit_id": "u-011-3b1d61", "page": 11, "quote": "Диаграммы геофизических методов глинистости — самопроизвольной поляризации, гамма-метода — напротив, широко применяют для выделения коллекторов в терригенном разрезе.", "numbers": [], "question": null},
    {"key": "c2", "text": "Задолго до количественных способов отрицательная аномалия СП и низкие показания ГМ считались признаками коллектора.", "kind": "observation", "unit_id": "u-011-3b1d61", "page": 11, "quote": "отрицательная аномалия на кривой СП и низкие показания на диаграмме ГМ использовались как признаки коллектора в терригенном разрезе", "numbers": [], "question": null},
    {"key": "c3", "text": "При пресном глинистом растворе пласты-коллекторы (песчаники и алевролиты) дают пониженные значения СП — отрицательную аномалию.", "kind": "observation", "unit_id": "u-011-7711c1", "page": 11, "quote": "пласты-коллекторы (песчаники и алевролиты) выделяются в терригенном разрезе на диаграмме СП пониженными значениями (отрицательной аномалией)", "numbers": [], "question": null},
    {"key": "c4", "text": "Против глин и плотных глинистых алевролитов-неколлекторов СП устойчиво держится на максимальных значениях — это линия глин.", "kind": "observation", "unit_id": "u-011-7711c1", "page": 11, "quote": "устойчивыми максимальными значениями СП (линия глин), характерными для глин и плотных глинистых алевролитов-неколлекторов", "numbers": [], "question": null},
    {"key": "c5", "text": "Величина аномалии ΔUСП тем больше, чем больше различие в минерализации и сопротивлении вод пласта и глинистого раствора.", "kind": "inference", "unit_id": "u-011-35b8f2", "page": 11, "quote": "тем больше, чем больше различие в минерализации и электрическом удельном сопротивлении пластовых вод и глинистого раствора", "numbers": [], "question": null},
    {"key": "c6", "text": "Величина аномалии тем больше, чем сильнее различаются коллектор и соседняя порода-неколлектор по глинистому материалу.", "kind": "inference", "unit_id": "u-011-35b8f2", "page": 11, "quote": "а также чем больше различаются по содержанию глинистого материала коллектор и вмещающая порода — неколлектор", "numbers": [], "question": null},
    {"key": "c7", "text": "Условие: бурение на пресном глинистом растворе, где ρг больше ρа (так записано в книге).", "kind": "assumption", "unit_id": "u-011-7711c1", "page": 11, "quote": "скважин на пресном глинистом растворе", "numbers": [], "question": null}
  ],
  "mechanism": [
    {"text": "СП — это запись естественной разности потенциалов в скважине. Против глин кривая держится на устойчивом максимуме — линии глин.", "claims": ["c4"], "hypothesis": false},
    {"text": "Пласт-коллектор при пресном растворе даёт пониженные значения. Разница с линией глин и есть аномалия, направленная вниз.", "claims": ["c3", "c7"], "hypothesis": false},
    {"text": "Размер аномалии задают два контраста. Первый — вода пласта против глинистого раствора по минерализации и сопротивлению. Второй — глинистость коллектора против соседней породы.", "claims": ["c5", "c6"], "hypothesis": false},
    {"text": "Чем меньше любой из контрастов, тем меньше аномалия. Значит, по величине аномалии судят о силе контраста.", "claims": ["c5", "c6"], "hypothesis": false}
  ],
  "practice": [
    {"text": "Специалист сначала находит на диаграмме СП линию глин: устойчивый максимум против глин и плотных глинистых алевролитов.", "claims": ["c4"], "hypothesis": false},
    {"text": "Затем смотрит, лежит ли пласт ниже этой линии. При пресном растворе такой пласт — кандидат в коллекторы.", "claims": ["c3", "c7"], "hypothesis": false},
    {"text": "Учитывает, что аномалия отражает контраст вод и глинистости, а не абсолютный уровень записи.", "claims": ["c5", "c6"], "hypothesis": false},
    {"text": "Слабую аномалию разумно перепроверить другими диаграммами. В этом фрагменте главы такой порядок прямо не описан.", "claims": [], "hypothesis": true}
  ],
  "nuances": [
    {"text": "Вывод о коллекторе сделан для пресного глинистого раствора (ρг > ρа). Для других растворов вывод в этом фрагменте не дан; см. узел n16.", "claims": ["c7"], "hypothesis": false},
    {"text": "Коллекторами здесь названы песчаники и алевролиты. Случаи других пород с пониженным СП разобраны в узле n14.", "claims": ["c3"], "hypothesis": false},
    {"text": "Аномалия задаётся относительно линии глин. Её нельзя понимать как самостоятельное значение записи.", "claims": ["c4", "c3"], "hypothesis": false}
  ],
  "deeper": [
    {"title": "Откуда берётся разность потенциалов", "text": "В главе физическая природа потенциала не раскрыта. Обычно её связывают с разной концентрацией солей у скважины и в пласте (диффузия ионов). Это вне главы.", "claims": [], "hypothesis": true},
    {"title": "Признак старше порогов", "text": "Книга говорит, что признак отрицательной аномалии использовали задолго до количественных способов выделения коллекторов.", "claims": ["c2"], "hypothesis": false}
  ],
  "procedure": [
    {"text": "Найти на диаграмме СП линию глин: устойчивые максимальные значения против глин и плотных глинистых алевролитов-неколлекторов.", "claims": ["c4"]},
    {"text": "Сравнить показания против пласта с этой линией. При пресном растворе пласт ниже линии — отрицательная аномалия, признак коллектора.", "claims": ["c3", "c7", "c2"]}
  ],
  "numbers_conditions": [
    {"text": "Условие: бурение на пресном глинистом растворе, при котором ρг > ρа (запись книги).", "claims": ["c7"]},
    {"text": "Числовых порогов для аномалии в этом фрагменте книга не задаёт; сравнение идёт относительно линии глин.", "claims": ["c3", "c4"]}
  ],
  "terms_defined": [
    {"term": "линия глин", "term_en": "shale baseline", "abbr": "", "definition": "Устойчивый максимум кривой СП против глин и плотных глинистых алевролитов-неколлекторов. От неё сравнивают показания пластов.", "claims": ["c4"]},
    {"term": "аномалия СП", "term_en": "SP anomaly", "abbr": "ΔUСП", "definition": "Отклонение кривой СП против пласта от линии глин. У коллектора при пресном растворе оно отрицательное, то есть показания ниже линии.", "claims": ["c3", "c5"]},
    {"term": "минерализация пластовых вод", "term_en": "formation water salinity", "abbr": "", "definition": "Количество солей, растворённых в воде, которая заполняет поры пласта. Текст сравнивает её с минерализацией глинистого раствора.", "claims": ["c5"]},
    {"term": "пресный раствор", "term_en": "fresh mud", "abbr": "", "definition": "Глинистый буровой раствор на пресной воде, с малым содержанием солей. В тексте он задаёт условие отрицательной аномалии.", "claims": ["c7"]},
    {"term": "алевролит", "term_en": "siltstone", "abbr": "", "definition": "Мелкообломочная порода: зёрна крупнее глинистых частиц и мельче песчаных.", "claims": ["c3"]}
  ],
