  "misconception": {
    "pack_id": null,
    "wrong": "Отрицательная аномалия СП — признак коллектора при любом растворе, а её величина ничего не значит.",
    "right": "Аномалия СП — отклонение от линии глин. Её величина отражает контраст вод и глинистости. При пресном растворе пласт-коллектор даёт её отрицательной.",
    "claims": ["c3", "c5", "c6", "c7"]
  },
  "data_meaning": {
    "inputs": [
      {"text": "Кривая СП против каждого пласта и линия глин в разрезе.", "claims": ["c3", "c4"], "hypothesis": false},
      {"text": "Тип бурового раствора: пресный или нет, со сравнением ρг и ρа.", "claims": ["c7"], "hypothesis": false},
      {"text": "Минерализация пластовых вод и глинистость соседних пород.", "claims": ["c5", "c6"], "hypothesis": false},
      {"text": "В цифровом виде кривая СП — ряд значений по глубине. Это форма записи вне главы.", "claims": [], "hypothesis": true}
    ],
    "outputs": [
      {"text": "Отклонение каждого пласта от линии глин: отрицательная аномалия или нет.", "claims": ["c3", "c4"], "hypothesis": false},
      {"text": "Признак коллектора в терригенном разрезе при пресном растворе.", "claims": ["c2", "c7"], "hypothesis": false}
    ],
    "breaks": [
      {"text": "Малая величина аномалии означает малый контраст вод или глинистости.", "claims": ["c5", "c6"], "hypothesis": false},
      {"text": "Вывод о коллекторе дан для пресного раствора; другой раствор меняет условие.", "claims": ["c7"], "hypothesis": false},
      {"text": "Шум на реальной кривой может размыть линию глин. Это вне главы.", "claims": [], "hypothesis": true}
    ]
  },
  "it_analogy": {
    "pack_id": "IT04",
    "analogy": "Линия глин работает как общая шкала: каждый пласт сравнивают с ней. Отклонение от неё — аномалия, как расхождение двух рядов после нормализации.",
    "breaks_where": "В IT04 совмещать ряды можно, если известно, что флюид — вода. Здесь опорой служит линия глин из того же разреза, а аномалия зависит от двух физических контрастов, которые не сводятся к одной поправке.",
    "hypothesis": true
  },
  "now_nuance": null,
